import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

import { generateSequentialReceiptNumber } from '@/lib/sequence';

async function generateReceiptNumber(companyCode: string): Promise<string> {
  return generateSequentialReceiptNumber(`RCP-${companyCode}`);
}


export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const emiScheduleId = searchParams.get('emiScheduleId');
    const paymentId = searchParams.get('paymentId');
    const isOffline = searchParams.get('isOffline') === 'true';
    const offlineLoanId = searchParams.get('offlineLoanId');

    if (!emiScheduleId && !paymentId) {
      return NextResponse.json({ error: 'EMI Schedule ID or Payment ID is required' }, { status: 400 });
    }

    // ============ HANDLE OFFLINE LOAN RECEIPT ============
    if (isOffline && emiScheduleId) {
      console.log(`[Receipt API] Fetching offline loan EMI receipt for EMI ID: ${emiScheduleId}, Loan ID: ${offlineLoanId}`);
      
      // Get the offline loan EMI
      const offlineEmi = await db.offlineLoanEMI.findUnique({
        where: { id: emiScheduleId },
        include: {
          offlineLoan: {
            include: {
              company: true
            }
          }
        }
      });

      if (!offlineEmi) {
        console.log(`[Receipt API] Offline EMI not found: ${emiScheduleId}`);
        return NextResponse.json({ error: 'EMI not found' }, { status: 404 });
      }

      // Check if EMI is paid
      if (offlineEmi.paymentStatus !== 'PAID' && offlineEmi.paymentStatus !== 'PARTIALLY_PAID' && offlineEmi.paymentStatus !== 'INTEREST_ONLY_PAID') {
        console.log(`[Receipt API] EMI not paid yet: ${offlineEmi.paymentStatus}`);
        return NextResponse.json({ error: 'EMI not paid yet' }, { status: 400 });
      }

      let loan = offlineEmi.offlineLoan;
      let company = loan.company;

      // Check for mirror loan mapping
      const mirrorMapping = await db.mirrorLoanMapping.findFirst({
        where: { 
          OR: [
            { originalLoanId: loan.id },
            { mirrorLoanId: loan.id }
          ]
        }
      });

      // Determine if this is a mirror loan (either directly, via mapping, or via mirror context ID)
      const isMirrorLoan = loan.isMirrorLoan || mirrorMapping?.mirrorLoanId === loan.id || (offlineLoanId && offlineLoanId !== loan.id);

      // If offlineLoanId is passed and matches the mirror loan, use the mirror company branding
      if (offlineLoanId && offlineLoanId !== loan.id) {
        const potentialMirrorLoan = await db.offlineLoan.findUnique({
          where: { id: offlineLoanId },
          include: { company: true }
        });
        if (potentialMirrorLoan && potentialMirrorLoan.isMirrorLoan && potentialMirrorLoan.originalLoanId === loan.id) {
          company = potentialMirrorLoan.company;
        }
      }

      const companyCode = company?.code || 'MM';

      // Get all EMIs for this loan to calculate totals
      const allEmis = await db.offlineLoanEMI.findMany({
        where: { offlineLoanId: loan.id }
      });
      
      const paidEmis = allEmis.filter(e => e.paymentStatus === 'PAID');
      const totalLoanAmount = loan.loanAmount;
      const totalPaidAmount = paidEmis.reduce((sum, e) => sum + (e.paidAmount || 0), 0);
      const balanceDue = totalLoanAmount - totalPaidAmount;
      const totalEmis = allEmis.length;

      const effectiveInterestRate = mirrorMapping?.mirrorInterestRate || loan.interestRate;

      // Generate receipt number
      const receiptNo = await generateReceiptNumber(companyCode);

      const receiptData = {
        receiptNo: receiptNo,
        date: offlineEmi.paidDate?.toISOString() || new Date().toISOString(),
        customerName: loan.customerName || '',
        fatherName: (loan as any).reference1Name || '',
        phone: loan.customerPhone || '',
        address: loan.customerAddress || '',
        loanAccountNo: loan.loanNumber || '',
        loanAmount: totalLoanAmount,
        interestRate: loan.interestRate || 0,
        mirrorInterestRate: effectiveInterestRate,
        tenure: loan.tenure || 0,
        emiNumber: offlineEmi.installmentNumber || 0,
        totalEmis: totalEmis,
        dueDate: offlineEmi.dueDate?.toISOString() || '',
        paymentDate: offlineEmi.paidDate?.toISOString() || new Date().toISOString(),
        // Use paidPrincipal/paidInterest for all modes (they always reflect the actual collected amount)
        principalAmount: offlineEmi.paymentStatus === 'INTEREST_ONLY_PAID'
          ? 0
          : (offlineEmi as any).paidPrincipal || offlineEmi.principalAmount || 0,
        interestAmount: (offlineEmi as any).paidInterest || offlineEmi.interestAmount || 0,
        totalAmount: offlineEmi.paidAmount || offlineEmi.totalAmount || 0,
        paymentMode: (offlineEmi as any).paymentMode || 'CASH',
        paymentReference: (offlineEmi as any).paymentReference || '',
        referenceNo: (offlineEmi as any).paymentReference || loan.loanNumber || '',
        balanceDue: Math.max(0, balanceDue),
        companyName: company?.name || 'Money Mitra',
        companyCode: companyCode,
        // Payment type flags
        isInterestOnly: offlineEmi.paymentStatus === 'INTEREST_ONLY_PAID',
        isPrincipalOnly: (offlineEmi as any).isPrincipalOnly === true,
        isPartialPayment: offlineEmi.paymentStatus === 'PARTIALLY_PAID',
        isMirrorLoan: isMirrorLoan,
        // Split payment breakdown
        isSplitPayment: (offlineEmi as any).isSplitPayment === true,
        splitCashAmount: (offlineEmi as any).splitCashAmount || 0,
        splitOnlineAmount: (offlineEmi as any).splitOnlineAmount || 0,
        // Penalty
        penaltyAmount: (offlineEmi as any).penaltyAmount || 0,
        penaltyWaived: (offlineEmi as any).penaltyWaiver || 0,
        // Remaining due on partial payment
        remainingDue: offlineEmi.paymentStatus === 'PARTIALLY_PAID'
          ? Math.max(0, (offlineEmi.totalAmount || 0) - (offlineEmi.paidAmount || 0))
          : 0,
      };

      console.log(`[Receipt API] Generated offline receipt: ${receiptNo} for EMI #${offlineEmi.installmentNumber}`);

      return NextResponse.json({
        success: true,
        receiptData,
        payment: {
          id: offlineEmi.id,
          receiptNumber: receiptNo,
          receiptGenerated: true,
          createdAt: offlineEmi.paidDate || new Date()
        }
      });
    }

    // ============ HANDLE ONLINE LOAN RECEIPT ============
    let payment;
    
    if (paymentId) {
      payment = await db.payment.findUnique({
        where: { id: paymentId },
        include: {
          emiSchedule: {
            include: {
              loanApplication: {
                include: {
                  company: true,
                  customer: {
                    select: {
                      id: true,
                      name: true,
                      phone: true,
                      address: true,
                      city: true,
                      state: true,
                      pincode: true
                    }
                  },
                  sessionForm: {
                    include: {
                      agent: {
                        select: { id: true, name: true, email: true }
                      }
                    }
                  }
                }
              }
            }
          },
          loanApplication: {
            include: {
              company: true,
              customer: {
                select: {
                  id: true,
                  name: true,
                  phone: true,
                  address: true,
                  city: true,
                  state: true,
                  pincode: true
                }
              },
              sessionForm: {
                include: {
                  agent: {
                    select: { id: true, name: true, email: true }
                  }
                }
              }
            }
          },
          customer: {
            select: {
              id: true,
              name: true,
              phone: true,
              address: true,
              city: true,
              state: true,
              pincode: true
            }
          }
        }
      });
    } else if (emiScheduleId) {
      // Fetch most recent COMPLETED payment — do NOT require receiptGenerated:true
      // Many payments are saved without that flag set
      payment = await db.payment.findFirst({
        where: { emiScheduleId, status: 'COMPLETED' },
        include: {
          emiSchedule: {
            include: {
              loanApplication: {
                include: {
                  company: true,
                  customer: {
                    select: {
                      id: true, name: true, phone: true,
                      address: true, city: true, state: true, pincode: true
                    }
                  },
                  sessionForm: {
                    include: { agent: { select: { id: true, name: true, email: true } } }
                  }
                }
              }
            }
          },
          loanApplication: {
            include: {
              company: true,
              customer: {
                select: {
                  id: true, name: true, phone: true,
                  address: true, city: true, state: true, pincode: true
                }
              },
              sessionForm: {
                include: { agent: { select: { id: true, name: true, email: true } } }
              }
            }
          },
          customer: {
            select: {
              id: true, name: true, phone: true,
              address: true, city: true, state: true, pincode: true
            }
          }
        },
        orderBy: { createdAt: 'desc' }
      });

      // If no receipt found, check if EMI is paid and generate receipt on the fly
      if (!payment) {
        const emi = await db.eMISchedule.findUnique({
          where: { id: emiScheduleId },
          include: {
            loanApplication: {
              include: {
                company: true,
                customer: {
                  select: {
                    id: true,
                    name: true,
                    phone: true,
                    address: true,
                    city: true,
                    state: true,
                    pincode: true
                  }
                },
                sessionForm: {
                  include: {
                    agent: {
                      select: { id: true, name: true, email: true }
                    }
                  }
                }
              }
            }
          }
        });

        // Check if EMI is paid (PAID or INTEREST_ONLY_PAID)
        if (emi && (emi.paymentStatus === 'PAID' || emi.paymentStatus === 'INTEREST_ONLY_PAID')) {
          const companyCode = emi.loanApplication?.company?.code || 'MM';
          
          // Find any existing payment for this EMI
          const existingPayment = await db.payment.findFirst({
            where: { emiScheduleId },
            orderBy: { createdAt: 'desc' }
          });

          if (existingPayment) {
            // Update existing payment with receipt info
            const receiptNo = await generateReceiptNumber(companyCode);
            payment = await db.payment.update({
              where: { id: existingPayment.id },
              data: {
                receiptGenerated: true,
                receiptNumber: receiptNo
              },
              include: {
                emiSchedule: {
                  include: {
                    loanApplication: {
                      include: {
                        company: true,
                        customer: {
                          select: {
                            id: true,
                            name: true,
                            phone: true,
                            address: true,
                            city: true,
                            state: true,
                            pincode: true
                          }
                        },
                        sessionForm: {
                          include: {
                            agent: {
                              select: { id: true, name: true, email: true }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            });
            console.log(`[Receipt API] Generated receipt for existing payment: ${receiptNo}`);
          } else {
            // Create a new payment record with receipt
            const receiptNo = await generateReceiptNumber(companyCode);
            payment = await db.payment.create({
              data: {
                loanApplicationId: emi.loanApplicationId,
                emiScheduleId: emi.id,
                customerId: emi.loanApplication?.customerId || '',
                // Use paidAmount first, then totalAmount as fallback
                amount: emi.paidAmount || emi.totalAmount || 0,
                // principalComponent: prefer paidPrincipal, then principalAmount
                principalComponent: (emi.paidPrincipal && emi.paidPrincipal > 0)
                  ? emi.paidPrincipal
                  : (emi.principalAmount || 0),
                // interestComponent: prefer paidInterest, then interestAmount
                interestComponent: (emi.paidInterest && emi.paidInterest > 0)
                  ? emi.paidInterest
                  : (emi.interestAmount || 0),
                paymentMode: emi.paymentMode || 'CASH',
                status: 'COMPLETED',
                receiptNumber: receiptNo,
                receiptGenerated: true,
                paidById: emi.loanApplication?.customerId || '',
                paymentType: emi.paymentStatus === 'INTEREST_ONLY_PAID' ? 'INTEREST_ONLY' : 'FULL_EMI'
              },
              include: {
                emiSchedule: {
                  include: {
                    loanApplication: {
                      include: {
                        company: true,
                        customer: {
                          select: {
                            id: true,
                            name: true,
                            phone: true,
                            address: true,
                            city: true,
                            state: true,
                            pincode: true
                          }
                        },
                        sessionForm: {
                          include: {
                            agent: {
                              select: { id: true, name: true, email: true }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            });
            console.log(`[Receipt API] Created new payment with receipt: ${receiptNo}`);
          }
        }
      }
    }

    if (!payment) {
      return NextResponse.json({ error: 'Receipt not found - EMI may not be paid yet' }, { status: 404 });
    }

    const emi = payment.emiSchedule;
    const loan = emi?.loanApplication || (payment as any).loanApplication;
    const customer = loan?.customer || (payment as any).customer;
    const company = loan?.company || (payment as any).loanApplication?.company;
    const sessionForm = loan?.sessionForm || (payment as any).loanApplication?.sessionForm;

    // Check for mirror loan and get mirror interest rate
    const mirrorMapping = await db.mirrorLoanMapping.findFirst({
      where: { originalLoanId: loan?.id }
    });

    // Use mirror interest rate if mirror loan exists, otherwise use original rate
    const effectiveInterestRate = mirrorMapping?.mirrorInterestRate || sessionForm?.interestRate || 0;

    // Get father/husband name from session form
    const fatherName = sessionForm?.fatherName || '';

    // Calculate balance due — use disbursedAmount as fallback for loanAmount
    const allEmis = await db.eMISchedule.findMany({
      where: { loanApplicationId: loan?.id }
    });
    const paidEmisForBalance = allEmis.filter(e => e.paymentStatus === 'PAID' || e.paymentStatus === 'INTEREST_ONLY_PAID');
    // sessionForm.loanAmount → loan.disbursedAmount → loan.approvedAmount → 0
    const totalLoanAmount =
      (sessionForm?.loanAmount && sessionForm.loanAmount > 0 ? sessionForm.loanAmount : 0) ||
      ((loan as any)?.disbursedAmount && (loan as any).disbursedAmount > 0 ? (loan as any).disbursedAmount : 0) ||
      ((loan as any)?.approvedAmount && (loan as any).approvedAmount > 0 ? (loan as any).approvedAmount : 0) ||
      0;
    const totalPaidAmount = paidEmisForBalance.reduce((sum, e) => sum + (e.paidAmount || 0), 0);
    const balanceDue = Math.max(0, totalLoanAmount - totalPaidAmount);
    const totalEmis = allEmis.length;

    // For interest-only payments, use the mirror interest rate to calculate interest
    let displayInterestAmount = payment.interestComponent || emi?.interestAmount || 0;
    
    // If this is a mirror loan transaction, use mirror interest
    if (mirrorMapping && emi) {
      const mirrorMonthlyRate = mirrorMapping.mirrorInterestRate / 12 / 100;
      displayInterestAmount = Math.round((Number(emi.outstandingPrincipal || 0) + Number(emi.principalAmount || 0)) * mirrorMonthlyRate * 100) / 100;
    }

    // Penalty info from EMI schedule
    const penaltyAmount = emi?.penaltyAmount || 0;
    const waivedAmount = emi?.waivedAmount || 0;

    // Fallback chain: principalComponent → paidPrincipal on EMI schedule → principalAmount
    const finalPrincipal =
      (payment.principalComponent && payment.principalComponent > 0)
        ? payment.principalComponent
        : ((emi?.paidPrincipal && emi.paidPrincipal > 0)
            ? emi.paidPrincipal
            : (emi?.principalAmount || 0));

    // Fallback chain: amount → paidAmount on EMI → totalAmount on EMI
    const finalTotal =
      (payment.amount && payment.amount > 0)
        ? payment.amount
        : ((emi?.paidAmount && emi.paidAmount > 0)
            ? emi.paidAmount
            : (emi?.totalAmount || 0));

    // Interest: same fallback strategy; use mirror-adjusted value if applicable
    const finalInterest =
      (payment.interestComponent && payment.interestComponent > 0)
        ? payment.interestComponent
        : ((emi?.paidInterest && emi.paidInterest > 0)
            ? emi.paidInterest
            : displayInterestAmount);

    const receiptData = {
      receiptNo: payment.receiptNumber || `RCP-${company?.code || 'MM'}-1`,
      date: payment.createdAt.toISOString(),
      customerName: (`${loan?.firstName || ''} ${loan?.lastName || ''}`).trim() || customer?.name || '',
      fatherName: fatherName || (loan as any)?.fatherName || '',
      phone: customer?.phone || loan?.phone || '',
      address: [customer?.address || loan?.address, customer?.city || loan?.city, customer?.state || loan?.state, customer?.pincode || loan?.pincode].filter(Boolean).join(', '),
      loanAccountNo: loan?.applicationNo || '',
      loanAmount: totalLoanAmount,
      interestRate: sessionForm?.interestRate || 0,
      mirrorInterestRate: effectiveInterestRate,
      tenure: sessionForm?.tenure || 0,
      emiNumber: emi?.installmentNumber || 0,
      totalEmis: totalEmis,
      dueDate: emi?.dueDate?.toISOString() || '',
      paymentDate: emi?.paidDate?.toISOString() || payment.createdAt.toISOString(),
      principalAmount: finalPrincipal,
      interestAmount: finalInterest,
      penaltyAmount,
      penaltyWaived: waivedAmount,
      totalAmount: finalTotal,
      paymentMode: payment.paymentMode || emi?.paymentMode || 'CASH',
      paymentReference: payment.utrNumber || payment.transactionId || '',
      referenceNo: payment.utrNumber || payment.transactionId || loan?.applicationNo || '',
      balanceDue: Math.max(0, balanceDue),
      companyName: company?.name || 'Money Mitra',
      companyCode: company?.code || 'MM',
      // Payment type flags
      isInterestOnly: payment.paymentType === 'INTEREST_ONLY' || emi?.paymentStatus === 'INTEREST_ONLY_PAID',
      isPrincipalOnly: payment.paymentType === 'PRINCIPAL_ONLY',
      isPartialPayment: emi?.paymentStatus === 'PARTIALLY_PAID',
      // Split payment
      isSplitPayment: (payment as any).isSplitPayment === true,
      splitCashAmount: (payment as any).splitCashAmount || 0,
      splitOnlineAmount: (payment as any).splitOnlineAmount || 0,
      // Remaining due on partial
      remainingDue: emi?.paymentStatus === 'PARTIALLY_PAID'
        ? Math.max(0, (emi.totalAmount || 0) - (emi.paidAmount || 0))
        : 0,
    };

    return NextResponse.json({
      success: true,
      receiptData,
      payment: {
        id: payment.id,
        receiptNumber: payment.receiptNumber,
        receiptGenerated: payment.receiptGenerated,
        createdAt: payment.createdAt
      }
    });

  } catch (error) {
    console.error('[Receipt API] Error:', error);
    return NextResponse.json({ 
      error: 'Failed to fetch receipt data',
      details: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}
